@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class OrderApiIT {
  @Autowired TestRestTemplate http;

  @Test void rejectsDuplicateIdempotencyKey() {
    var headers = new HttpHeaders();
    headers.set("Idempotency-Key", "same-key");
    assertThat(http.postForEntity("/orders", new HttpEntity<>(command, headers), Order.class).getStatusCode()).isEqualTo(HttpStatus.CREATED);
    assertThat(http.postForEntity("/orders", new HttpEntity<>(command, headers), ProblemDetail.class).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
  }
}

@Transactional
public Order place(CreateOrder command) {
  Order order = orderRepository.save(Order.create(command));
  outboxRepository.save(OutboxEvent.of("OrderCreated", order.getId(), payload(order)));
  return order;
}

// Un relay publie ensuite l’outbox et marque l’événement envoyé.
